import java.io.*;
import java.util.*;

public class ar {
    static BufferedReader reader;
    static StringTokenizer tokenizer;
    static Map<Integer, Integer> costMap;
    static int[] values;

    public static void main(String[] args) {
        reader = new BufferedReader(new InputStreamReader(System.in));
        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static void solve() throws Exception {
        int n = nextInt(), budget = nextInt();
        values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = nextInt();
        }

        if (n % 2 != 0) {
            System.out.print(0);
            return;
        }

        costMap = new HashMap<>();
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < n; i++) {
            if (values[i] % 2 == 0) evenCount++;
            else oddCount++;
            if (evenCount > 0 && oddCount > 0 && evenCount == oddCount && i + 1 < n) {
                costMap.put(i, Math.abs(values[i] - values[i + 1]));
            }
        }

        if (costMap.size() == 0) {
            System.out.print(0);
            return;
        }

        List<Integer> costs = new ArrayList<>(costMap.values());
        Collections.sort(costs);

        if (costs.size() == 1) {
            System.out.println(costs.get(0) <= budget ? 1 : 0);
            return;
        }

        int count = 0;
        for (int c : costs) {
            if (c <= budget) {
                budget -= c;
                count++;
            } else {
                break;
            }
        }
        System.out.print(count);
    }

    static String next() throws Exception {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    static int nextInt() throws Exception {
        return Integer.parseInt(next());
    }

    static long nextLong() throws Exception {
        return Long.parseLong(next());
    }

    static double nextDouble() throws Exception {
        return Double.parseDouble(next());
    }

    static String nextLine() throws Exception {
        return reader.readLine();
    }
}
